      "ceramide_low": {
        "id": "ceramide_low",
        "kind": "statement",
        "label": "In eczema, the outer skin layer holds less ceramide",
        "quote": "The compromised skin barrier is mainly attributable to significantly decreased levels of ceramides in the stratum corneum (SC) in lesional and non‐lesional skin."
      },
      "cleanser_daily": {
        "id": "cleanser_daily",
        "kind": "context",
        "label": "Cleanser: massaged into wet skin over the whole body once a day, then rinsed",
        "quote": "Patients were instructed to massage the cleanser into wet skin across their whole body once daily, rinse with water and pat dry, for 28 days. Patients were also required to apply the cream liberally to their whole body, in particular eczema‐prone areas, twice daily, morning and night for 28 days. One application of cream was required after daily body cleansing. In addition, patients were supplied with mometasone furoate 0.1% w/w (Zatamil Hydrogel; Ego Pharmaceuticals Pty. Ltd., Braeside, Victoria, Australia) to be used as rescue medication for the duration of the study in place of their usual topical corticosteroids or calcineurin inhibitors."
      },
